def detect_formality(client: OpenAI, model: str, text: str) -> str:
    messages = [
        {"role": "user", "content": DETECT_PROMPT.format(text=text[:1000])},
    ]
    result = _call_llm(client, model, messages).lower().strip().rstrip(".")
    if "formal" in result and "casual" not in result:
        return "formal"
    return "casual"


def generate_counterfactual(client: OpenAI, model: str, text: str, original_formality: str) -> tuple[str, str]:
    """Returns (counterfactual_text, double_rewrite_text)."""
    target = "casual" if original_formality == "formal" else "formal"

    # Step 1: flip
    msgs_flip = _build_rewrite_prompt(text, target)
    counterfactual = _call_llm(client, model, msgs_flip)

    # Step 2: flip back
    msgs_flipback = _build_rewrite_prompt(counterfactual, original_formality)
    double_rewrite = _call_llm(client, model, msgs_flipback)

